const H=(main,o)=>NV.head(main,o);
const append=(main,html)=>{const el=NV.el(html);main.appendChild(el);return el};

function pageHome(main){
  const d=db();const months=monthsBack(12);const cur=months[11].key,prev=months[10].key;
  const salesBy=k=>d.invoices.filter(i=>i.status!=="draft"&&ym(i.date)===k).reduce((s,i)=>s+calc(i).ht,0);
  const buyBy=k=>d.sinvoices.filter(i=>ym(i.date)===k).reduce((s,i)=>s+calc(i).ht,0);
  const day=TODAY.getDate();const sc=salesBy(cur),sp=d.invoices.filter(i=>i.status!=="draft"&&ym(i.date)===prev&&Number(i.date.slice(8,10))<=day).reduce((s,i)=>s+calc(i).ht,0);
  const open=d.invoices.filter(i=>["unpaid","partial","overdue"].includes(payStatus(i)));const ar=open.reduce((s,i)=>s+calc(i).rest,0);const overdue=open.filter(i=>payStatus(i)==="overdue").reduce((s,i)=>s+calc(i).rest,0);
  const moAct=d.mos.filter(m=>m.status==="inprogress"),alerts=d.products.filter(p=>p.min&&stockT(p)<p.min);
  H(main,{icon:"grid",title:tr("Panel general","Overview"),sub:esc(d.company.name)+" · "+dateL(TODAY),actions:`<button class="btn" data-a="newQuote">${icon("plus")}${tr("Presupuesto","Quote")}</button><button class="btn pri" data-a="newInvoice">${icon("plus")}${tr("Factura","Invoice")}</button>`});
  append(main,`<div class="g g4">${NV.kpi("money",tr("Facturación del mes","Sales this month"),money(sc),"",(sp?((sc-sp)/sp*100>=0?"+":"")+num((sc-sp)/sp*100,1)+"% "+tr("vs. mismo período del mes anterior","vs same period last month"):""))}${NV.kpi("clock",tr("Cuentas por cobrar","Accounts receivable"),money(ar),"warn",overdue?"-"+money(overdue)+" "+tr("vencido","overdue"):"")}${NV.kpi("factory",tr("OF en curso","MOs in progress"),num(moAct.length),"vio",num(d.mos.filter(m=>m.status==="validated").length)+" "+tr("por iniciar","to start"))}${NV.kpi("alert",tr("Productos bajo mínimo","Items below minimum"),num(alerts.length),"bad")}</div>`);
  const g=append(main,`<div class="g g-2-1 mt"><div class="card"><div class="card-h"><h3>${icon("chart")}${tr("Ventas vs. compras (12 meses, sin IVA)","Sales vs purchases (12 months, net)")}</h3></div><div class="card-b"><div class="chart"><canvas id="c1"></canvas></div></div></div>
   <div class="card"><div class="card-h"><h3>${icon("bank")}${tr("Saldos bancarios","Bank balances")}</h3><a class="small" href="#/bank">${tr("Ver todo","View all")}</a></div><ul class="list-mini">${d.banks.map(b=>`<li><div class="l"><span class="kpi" style="padding:0"><span class="ki">${icon("bank")}</span></span><div><b>${esc(b.short)}</b><small>${esc(b.number)}</small></div></div><b class="num">${money(bankBal(b.id))}</b></li>`).join("")}<li><div class="l"><div><b>${tr("Total disponible","Total available")}</b></div></div><b class="num" style="font-size:16px">${money(d.banks.reduce((s,b)=>s+bankBal(b.id),0))}</b></li></ul>
   <div class="card-b" style="border-top:1px solid var(--line-2)"><div class="chart sm"><canvas id="c2"></canvas></div></div></div></div>`);
  chart($("#c1",g),{type:"bar",money:true,data:{labels:months.map(m=>m.label),datasets:[{label:tr("Ventas","Sales"),data:months.map(m=>salesBy(m.key))},{label:tr("Compras","Purchases"),data:months.map(m=>buyBy(m.key)),color:"#7A5AF8"},{type:"line",label:tr("Margen bruto","Gross margin"),data:months.map(m=>salesBy(m.key)-buyBy(m.key)),color:"#12A06A",pointRadius:3}]}});
  const byCat={};d.invoices.filter(i=>i.status!=="draft"&&ym(i.date)>=months[0].key).forEach(i=>{const s=TP(i.tp).sector;const k=NV.L(s||["Otros","Other"]);byCat[k]=(byCat[k]||0)+calc(i).ht});
  const cats=Object.entries(byCat).sort((a,b)=>b[1]-a[1]);
  chart($("#c2",g),{type:"doughnut",money:true,data:{labels:cats.map(c=>c[0]),datasets:[{data:cats.map(c=>Math.round(c[1]))}]},options:{plugins:{legend:{position:"right",labels:{boxWidth:9,usePointStyle:true,font:{size:11}}},title:{display:true,text:tr("Ventas por industria","Sales by industry"),align:"start",color:NV.css("--ink-2")}}}});
  const lastInv=d.invoices.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);
  const openQ=d.quotes.filter(q=>q.status==="open").slice(-6).reverse();
  const moList=d.mos.filter(m=>m.status==="inprogress"||m.status==="validated").slice(0,6);
  const supDue=d.sinvoices.filter(i=>payStatus(i)!=="paid").sort((a,b)=>a.due.localeCompare(b.due)).slice(0,6);
  append(main,`<div class="g g3 mt">
   <div class="card"><div class="card-h"><h3>${icon("invoice")}${tr("Últimas facturas","Latest invoices")}</h3><a class="small" href="#/billing">${tr("Ver todas","View all")}</a></div><ul class="list-mini">${lastInv.map(i=>`<li><div class="l"><div><a class="ref" href="#/billing/invoice/${i.id}">${i.ref}</a><small> · ${esc(TP(i.tp).name)}</small></div></div><div style="text-align:right"><b class="num">${money(calc(i).ttc)}</b><div>${stBadge("invoice",payStatus(i))}</div></div></li>`).join("")}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("factory")}${tr("Producción en curso","Production in progress")}</h3><a class="small" href="#/mrp">${tr("Ver todas","View all")}</a></div><ul class="list-mini">${moList.map(m=>{const pc=Math.round(m.produced/m.qty*100);return `<li><div class="l" style="flex:1"><div style="flex:1"><a class="ref" href="#/mrp/mo/${m.id}">${m.ref}</a> <small>· ${esc(NV.L(LINES.find(l=>l.id===m.line)?.name||"—"))}</small><b style="font-weight:600">${esc(pname(m.product))}</b><div class="bar" style="margin-top:6px"><i style="width:${pc}%"></i></div></div></div><div class="num small"><b>${num(m.produced)}/${num(m.qty)}</b><br><span class="muted">${pc}%</span></div></li>`}).join("")}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("alert")}${tr("Alertas de stock","Stock alerts")}</h3><a class="small" href="#/stock/alerts">${tr("Ver todas","View all")}</a></div><ul class="list-mini">${alerts.slice(0,6).map(p=>`<li><div class="l"><div><a href="#/products/card/${p.id}" class="ref">${p.id}</a><b style="font-weight:600">${esc(NV.L(p.name))}</b></div></div><div class="num small"><b class="down">${num(stockT(p))}</b> / ${num(p.min)} ${esc(p.unit)}</div></li>`).join("")||`<li class="muted">${tr("Sin alertas","No alerts")}</li>`}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("file")}${tr("Presupuestos abiertos","Open quotes")}</h3><a class="small" href="#/commercial">${tr("Ver todos","View all")}</a></div><ul class="list-mini">${openQ.map(q=>`<li><div class="l"><div><a class="ref" href="#/commercial/quote/${q.id}">${q.ref}</a><small> · ${esc(TP(q.tp).name)}</small></div></div><b class="num">${money(calc(q).ttc)}</b></li>`).join("")||`<li class="muted">—</li>`}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("clock")}${tr("Próximos pagos a proveedores","Upcoming supplier payments")}</h3><a class="small" href="#/purchases/invoices">${tr("Ver todos","View all")}</a></div><ul class="list-mini">${supDue.map(i=>`<li><div class="l"><div><a class="ref" href="#/purchases/invoice/${i.id}">${i.ref}</a><small> · ${esc(TP(i.tp).name)}</small><br><small>${tr("Vence","Due")} ${date(i.due)}</small></div></div><div style="text-align:right"><b class="num">${money(calc(i).rest)}</b><div>${stBadge("sinvoice",payStatus(i))}</div></div></li>`).join("")||`<li class="muted">—</li>`}</ul></div>
   <div class="card"><div class="card-h"><h3>${icon("cart")}${tr("Pedidos por despachar","Orders to ship")}</h3><a class="small" href="#/commercial/orders">${tr("Ver todos","View all")}</a></div><ul class="list-mini">${d.orders.filter(o=>o.status==="validated"||o.status==="inprocess").slice(0,6).map(o=>`<li><div class="l"><div><a class="ref" href="#/commercial/order/${o.id}">${o.ref}</a><small> · ${esc(TP(o.tp).name)}</small><br><small>${tr("Entrega","Delivery")} ${date(o.delivery)}</small></div></div>${stBadge("order",o.status)}</li>`).join("")||`<li class="muted">—</li>`}</ul></div>
  </div>`);
  bindActs(main);
}

