const KINDL={customer:[["Cliente","Customer"],"blue"],supplier:[["Proveedor","Supplier"],"vio"],prospect:[["Prospecto","Prospect"],"warn"]};
function tpRevenue(id){return db().invoices.filter(i=>i.tp===id&&i.status!=="draft").reduce((s,i)=>s+calc(i).ht,0)}
function tpBalance(id){return db().invoices.filter(i=>i.tp===id).reduce((s,i)=>s+calc(i).rest,0)+db().sinvoices.filter(i=>i.tp===id).reduce((s,i)=>s+calc(i).rest,0)}
function pageTpList(main,kind){
  const ttl=kind?{customer:tr("Clientes","Customers"),supplier:tr("Proveedores","Suppliers"),prospect:tr("Prospectos","Prospects")}[kind]:tr("Terceros","Third parties");
  H(main,{crumbs:[[tr("Terceros","Third parties"),"#/tp"]],icon:"building",title:ttl,sub:tr("Empresas con las que opera la planta: clientes, proveedores y prospectos.","Companies the plant works with: customers, suppliers and prospects."),actions:`<button class="btn pri" data-a="newTp">${icon("plus")}${tr("Nuevo tercero","New third party")}</button>`});
  table(main,{name:"terceros",rows:()=>db().tps.filter(t=>!kind||t.kind===kind),onRow:x=>NV.go("#/tp/card/"+x.id),sort:"name",
    filters:[...(kind?[]:[{k:"kind",label:tr("Tipo","Type"),options:Object.entries(KINDL).map(([k,v])=>[k,v[0]])}]),{k:"prov",label:tr("Provincia","Province"),options:[...new Set(db().tps.map(t=>t.prov))].sort()},{k:"rep",label:tr("Vendedor","Sales rep"),options:REPS}],
    columns:[{k:"name",label:tr("Razón social","Company"),render:x=>`<div style="display:flex;gap:10px;align-items:center"><span class="av sm">${initials(x.name)}</span><div><b>${esc(x.name)}</b><div class="small muted">${esc(x.email)}</div></div></div>`},
      {k:"kind",label:tr("Tipo","Type"),render:x=>badge(NV.L(KINDL[x.kind][0]),KINDL[x.kind][1]),text:x=>NV.L(KINDL[x.kind][0])},
      {k:"cuit",label:"CUIT",render:x=>`<span class="tag">${x.cuit}</span>`},{k:"city",label:tr("Localidad","City"),render:x=>esc(x.city+", "+x.prov),text:x=>x.city+", "+x.prov},
      {k:"rep",label:tr("Vendedor","Sales rep")},{k:"rev",label:tr("Facturado 12m","Billed 12m"),r:1,sv:x=>tpRevenue(x.id),text:x=>Math.round(tpRevenue(x.id)),render:x=>x.kind==="customer"?money(tpRevenue(x.id)):"<span class='muted'>—</span>"},
      {k:"bal",label:tr("Saldo","Balance"),r:1,sv:x=>tpBalance(x.id),text:x=>Math.round(tpBalance(x.id)),render:x=>{const b=tpBalance(x.id);return b>0?`<b>${money(b)}</b>`:"<span class='muted'>0</span>"}}]});
  bindActs(main);
}
function pageContacts(main){
  H(main,{crumbs:[[tr("Terceros","Third parties"),"#/tp"]],icon:"phone",title:tr("Contactos","Contacts")});
  const rows=[];db().tps.forEach(t=>t.contacts.forEach(c=>rows.push({...c,tp:t.id,tpn:t.name,kind:t.kind})));
  table(main,{name:"contactos",rows,sort:"name",onRow:x=>NV.go("#/tp/card/"+x.tp),filters:[{k:"kind",label:tr("Tipo","Type"),options:Object.entries(KINDL).map(([k,v])=>[k,v[0]])}],
    columns:[{k:"name",label:tr("Nombre","Name"),render:x=>`<b>${esc(x.name)}</b>`},{k:"role",label:tr("Cargo","Role"),render:x=>esc(NV.L(x.role)),text:x=>NV.L(x.role)},{k:"tpn",label:tr("Empresa","Company"),render:x=>tpLink(x.tp)},{k:"email",label:"Email",render:x=>`<span class="small">${esc(x.email)}</span>`},{k:"phone",label:tr("Teléfono","Phone"),cls:"nowrap"}]});
}
function tpFields(){return [{k:"name",label:tr("Razón social","Company name"),req:1,full:1},{k:"kind",label:tr("Tipo","Type"),type:"select",options:Object.entries(KINDL).map(([k,v])=>[k,v[0]])},{k:"cuit",label:"CUIT",ph:"30-12345678-9"},{k:"email",label:"Email",type:"email"},{k:"phone",label:tr("Teléfono","Phone")},{k:"address",label:tr("Dirección","Address"),full:1},{k:"city",label:tr("Localidad","City")},{k:"prov",label:tr("Provincia","Province"),def:"Córdoba"},{k:"rep",label:tr("Vendedor asignado","Sales rep"),type:"select",options:REPS},{k:"terms",label:tr("Condición de pago (días)","Payment terms (days)"),type:"number",def:30},{k:"credit",label:tr("Límite de crédito (US$)","Credit limit (US$)"),type:"number",def:0},{k:"notes",label:tr("Notas","Notes"),type:"textarea",full:1}]}
function newTp(kind){formModal({title:tr("Nuevo tercero","New third party"),fields:tpFields(),vals:{kind:kind||"customer"},onSave:v=>{const id="T"+String(db().tps.length+1).padStart(3,"0")+Math.random().toString(36).slice(2,4);db().tps.push({id,...v,country:"Argentina",sector:["Industria","Industry"],supplies:[],contacts:[],created:iso(TODAY)});save();toast(NV.t("created"));NV.go("#/tp/card/"+id)}})}
function pageTpCard(main,{id}){
  const t=TP(id);if(!t.id)return notFound(main);
  H(main,{crumbs:[[tr("Terceros","Third parties"),"#/tp"],t.name],icon:"building",title:t.name,actions:`<button class="btn" data-e>${icon("edit")}${NV.t("edit")}</button>${t.kind!=="supplier"?`<button class="btn" data-a="newQuote" data-tp="${t.id}">${icon("file")}${tr("Presupuesto","Quote")}</button><button class="btn pri" data-a="newInvoice" data-tp="${t.id}">${icon("invoice")}${tr("Factura","Invoice")}</button>`:`<button class="btn pri" data-a="newSorder" data-tp="${t.id}">${icon("truck")}${tr("Pedido de compra","Purchase order")}</button>`}`});
  const inv=db().invoices.filter(i=>i.tp===id),si=db().sinvoices.filter(i=>i.tp===id),qs=db().quotes.filter(q=>q.tp===id),os=db().orders.filter(o=>o.tp===id),so=db().sorders.filter(o=>o.tp===id);
  const rev=tpRevenue(id),bal=tpBalance(id);
  append(main,`<div class="card"><div class="rec-h"><div class="big">${initials(t.name)}</div><div style="flex:1;min-width:200px"><h2>${esc(t.name)}</h2><div class="meta">${badge(NV.L(KINDL[t.kind][0]),KINDL[t.kind][1])}<span class="tag">CUIT ${esc(t.cuit)}</span><span class="muted small">${icon("building")} ${esc(t.city)}, ${esc(t.prov)}</span></div></div>
   <div class="g g3" style="flex:1;min-width:280px;gap:10px">${t.kind==="supplier"?`<div><small class="muted">${tr("Comprado 12m","Purchased 12m")}</small><div class="strong">${money(si.reduce((s,i)=>s+calc(i).ht,0))}</div></div>`:`<div><small class="muted">${tr("Facturado 12m","Billed 12m")}</small><div class="strong">${money(rev)}</div></div>`}<div><small class="muted">${tr("Saldo pendiente","Outstanding")}</small><div class="strong ${bal>0?"down":""}">${money(bal)}</div></div><div><small class="muted">${tr("Límite de crédito","Credit limit")}</small><div class="strong">${t.credit?money(t.credit):"—"}</div></div></div></div></div>`);
  const host=append(main,`<div class="mt"></div>`);
  NV.tabs(host,[{id:"info",label:tr("Ficha","Details"),icon:"info"},{id:"contacts",label:tr("Contactos","Contacts"),icon:"phone",count:t.contacts.length},{id:"docs",label:tr("Documentos","Documents"),icon:"file",count:inv.length+si.length+qs.length+os.length+so.length},{id:"stats",label:tr("Estadísticas","Statistics"),icon:"chart"}],(tab,b)=>{
    if(tab==="info")b.innerHTML=`<div class="g g2"><div class="card card-b"><dl class="dl"><dt>${tr("Razón social","Company")}</dt><dd>${esc(t.name)}</dd><dt>CUIT</dt><dd>${esc(t.cuit)}</dd><dt>${tr("Dirección","Address")}</dt><dd>${esc(t.address||"—")}</dd><dt>${tr("Localidad","City")}</dt><dd>${esc(t.city)}, ${esc(t.prov)}, ${esc(t.country||"Argentina")}</dd><dt>Email</dt><dd>${esc(t.email)}</dd><dt>${tr("Teléfono","Phone")}</dt><dd>${esc(t.phone)}</dd></dl></div>
      <div class="card card-b"><dl class="dl"><dt>${tr("Industria","Industry")}</dt><dd>${esc(NV.L(t.sector||"—"))}</dd><dt>${tr("Vendedor","Sales rep")}</dt><dd>${esc(t.rep)}</dd><dt>${tr("Condición de pago","Payment terms")}</dt><dd>${t.terms} ${tr("días","days")}</dd><dt>${tr("Cliente desde","Customer since")}</dt><dd>${date(t.created)}</dd>${t.supplies&&t.supplies.length?`<dt>${tr("Provee","Supplies")}</dt><dd>${t.supplies.map(p=>`<a href="#/products/card/${p}" class="tag">${p}</a>`).join(" ")}</dd>`:""}<dt>${NV.t("notes")}</dt><dd>${esc(t.notes||"—")}</dd></dl></div></div>`;
    if(tab==="contacts"){b.innerHTML=`<div class="acts" style="margin-bottom:12px"><button class="btn" data-nc>${icon("plus")}${tr("Agregar contacto","Add contact")}</button></div>`;
      table(b,{rows:t.contacts,name:"contactos",columns:[{k:"name",label:tr("Nombre","Name"),render:x=>`<b>${esc(x.name)}</b>`},{k:"role",label:tr("Cargo","Role"),render:x=>esc(NV.L(x.role)),text:x=>NV.L(x.role)},{k:"email",label:"Email"},{k:"phone",label:tr("Teléfono","Phone")}]});
      $("[data-nc]",b).onclick=()=>formModal({title:tr("Nuevo contacto","New contact"),fields:[{k:"name",label:tr("Nombre","Name"),req:1},{k:"role",label:tr("Cargo","Role")},{k:"email",label:"Email",type:"email"},{k:"phone",label:tr("Teléfono","Phone")}],onSave:v=>{t.contacts.push(v);save();toast(NV.t("created"));NV.render()}})}
    if(tab==="docs"){const rows=[].concat(qs.map(x=>["quote",x]),os.map(x=>["order",x]),inv.map(x=>["invoice",x]),so.map(x=>["sorder",x]),si.map(x=>["sinvoice",x])).map(([k,x])=>({k,x,date:x.date,ref:x.ref}));
      table(b,{rows,name:"documentos",sort:"date",dir:-1,onRow:r=>NV.go("#/"+KIND[r.k].base+"/"+r.x.id),filters:[{k:"k",label:tr("Tipo","Type"),options:Object.keys(KIND).map(k=>[k,KIND[k].one])}],
        columns:[{k:"ref",label:NV.t("ref"),render:r=>`<span class="ref">${r.ref}</span>`},{k:"k",label:tr("Tipo","Type"),render:r=>esc(NV.L(KIND[r.k].one)),text:r=>NV.L(KIND[r.k].one)},{k:"date",label:NV.t("date"),render:r=>date(r.date)},{k:"tot",label:NV.t("total"),r:1,sv:r=>calc(r.x).ttc,render:r=>money(calc(r.x).ttc)},{k:"st",label:NV.t("status"),render:r=>stBadge(r.k,stKey(r.k,r.x)),nocsv:1}]})}
    if(tab==="stats"){b.innerHTML=`<div class="card card-b"><div class="chart"><canvas></canvas></div></div>`;const ms=monthsBack(12);const src=t.kind==="supplier"?si:inv;chart($("canvas",b),{type:"bar",money:true,data:{labels:ms.map(m=>m.label),datasets:[{label:t.kind==="supplier"?tr("Compras","Purchases"):tr("Facturación","Sales"),data:ms.map(m=>src.filter(i=>ym(i.date)===m.key&&i.status!=="draft").reduce((s,i)=>s+calc(i).ht,0))}]}})}
  });
  $("[data-e]",main).onclick=()=>formModal({title:NV.t("edit")+" · "+t.name,fields:tpFields(),vals:t,onSave:v=>{Object.assign(t,v);save();toast(NV.t("saved"));NV.render()}});
  bindActs(main);
}

/* ---------- products ---------- */
function pageProducts(main,{type}={}){
  H(main,{crumbs:[[tr("Productos","Products"),"#/products"]],icon:"box",title:type?NV.L(CATS[type]):tr("Productos y servicios","Products & services"),sub:tr("Catálogo con costos calculados desde la lista de materiales y la mano de obra.","Catalog with costs rolled up from the bill of materials and labor."),actions:`<button class="btn pri" data-a="newProduct">${icon("plus")}${tr("Nuevo producto","New product")}</button>`});
  table(main,{name:"productos",rows:()=>db().products.filter(p=>!type||p.type===type),onRow:x=>NV.go("#/products/card/"+x.id),sort:"id",pageSize:15,
    filters:type?[]:[{k:"type",label:tr("Tipo","Type"),options:Object.entries(CATS)}],
    columns:[{k:"id",label:NV.t("ref"),render:x=>`<span class="ref">${x.id}</span>`},{k:"name",label:tr("Etiqueta","Label"),render:x=>`<b>${esc(NV.L(x.name))}</b>`,text:x=>NV.L(x.name),sv:x=>NV.L(x.name)},
      {k:"type",label:tr("Tipo","Type"),render:x=>badge(NV.L(CATS[x.type]),{PT:"blue",SE:"vio",MP:"",SV:"ok"}[x.type]),text:x=>NV.L(CATS[x.type])},
      {k:"price",label:tr("Precio venta","Sale price"),r:1,render:x=>money(x.price,2)},{k:"cost",label:tr("Costo","Cost"),r:1,render:x=>money(x.cost,2)},
      {k:"mg",label:tr("Margen","Margin"),r:1,sv:x=>x.price?(x.price-x.cost)/x.price:0,text:x=>x.price?Math.round((x.price-x.cost)/x.price*100)+"%":"",render:x=>{const m=x.price?(x.price-x.cost)/x.price*100:0;return `<span class="${m<20?"down":"up"}">${num(m,1)}%</span>`}},
      {k:"stock",label:"Stock",r:1,sv:x=>stockT(x),text:x=>stockT(x),render:x=>x.type==="SV"?"<span class='muted'>—</span>":`<b class="${x.min&&stockT(x)<x.min?"down":""}">${num(stockT(x),stockT(x)%1?1:0)}</b> <span class="muted small">${esc(x.unit)}</span>`},
      {k:"val",label:tr("Valorizado","Value"),r:1,sv:x=>stockT(x)*x.cost,text:x=>Math.round(stockT(x)*x.cost),render:x=>x.type==="SV"?"—":money(stockT(x)*x.cost)}]});
  bindActs(main);
}
function prodFields(){return [{k:"id",label:NV.t("ref"),req:1},{k:"type",label:tr("Tipo","Type"),type:"select",options:Object.entries(CATS)},{k:"nameEs",label:tr("Etiqueta","Label"),req:1,full:1},{k:"unit",label:tr("Unidad","Unit"),def:"u"},{k:"price",label:tr("Precio de venta (US$)","Sale price (US$)"),type:"number",step:"0.01"},{k:"cost",label:tr("Costo (US$)","Cost (US$)"),type:"number",step:"0.01"},{k:"min",label:tr("Stock mínimo","Minimum stock"),type:"number"},{k:"barcode",label:tr("Código de barras","Barcode")},{k:"desc",label:NV.t("desc"),type:"textarea",full:1}]}
function newProduct(){formModal({title:tr("Nuevo producto","New product"),fields:prodFields(),vals:{type:"PT"},onSave:v=>{if(P(v.id)){toast(tr("Esa referencia ya existe","That reference already exists"));return false}db().products.push({id:v.id,name:[v.nameEs,v.nameEs],type:v.type,unit:v.unit,price:v.price,cost:v.cost,min:v.min,barcode:v.barcode,desc:v.desc,line:null,stock:{W1:0,W2:0,W3:0},active:true});save();toast(NV.t("created"));NV.go("#/products/card/"+v.id)}})}
function pageProductCard(main,{id}){
  const p=P(id);if(!p)return notFound(main);const bom=db().boms.find(b=>b.product===id);
  H(main,{crumbs:[[tr("Productos","Products"),"#/products"],p.id],icon:"box",title:NV.L(p.name),sub:`<span class="ref">${p.id}</span> · ${esc(NV.L(CATS[p.type]))}`,actions:`<button class="btn" data-e>${icon("edit")}${NV.t("edit")}</button>${p.type!=="SV"?`<button class="btn" data-a="correct" data-p="${p.id}">${icon("edit")}${tr("Corregir stock","Adjust stock")}</button><button class="btn" data-a="transfer" data-p="${p.id}">${icon("move")}${tr("Transferir","Transfer")}</button>`:""}${bom?`<button class="btn pri" data-a="newMO" data-p="${p.id}">${icon("factory")}${tr("Fabricar","Manufacture")}</button>`:""}`});
  const m=p.price?(p.price-p.cost)/p.price*100:0;
  append(main,`<div class="g g4">${NV.kpi("money",tr("Precio de venta","Sale price"),money(p.price,2))}${NV.kpi("layers",tr("Costo unitario","Unit cost"),money(p.cost,2),"vio")}${NV.kpi("pie",tr("Margen","Margin"),num(m,1)+"%",m<20?"bad":"ok")}${NV.kpi("warehouse",tr("Stock total","Total stock"),p.type==="SV"?"—":num(stockT(p))+" "+esc(p.unit),p.min&&stockT(p)<p.min?"bad":"")}</div>`);
  const host=append(main,`<div class="mt"></div>`);
  const sold=[];db().invoices.forEach(i=>i.lines.forEach(l=>{if(l.p===id)sold.push({inv:i,l})}));
  NV.tabs(host,[{id:"info",label:tr("Ficha","Details"),icon:"info"},{id:"stock",label:"Stock",icon:"warehouse"},...(bom?[{id:"bom",label:"BOM",icon:"layers"}]:[]),{id:"moves",label:tr("Movimientos","Movements"),icon:"move"},{id:"sales",label:tr("Ventas","Sales"),icon:"chart",count:sold.length}],(tab,b)=>{
    if(tab==="info")b.innerHTML=`<div class="g g2"><div class="card card-b"><dl class="dl"><dt>${NV.t("ref")}</dt><dd><span class="ref">${p.id}</span></dd><dt>${tr("Etiqueta","Label")}</dt><dd>${esc(NV.L(p.name))}</dd><dt>${tr("Tipo","Type")}</dt><dd>${esc(NV.L(CATS[p.type]))}</dd><dt>${tr("Unidad","Unit")}</dt><dd>${esc(p.unit)}</dd><dt>${tr("Código de barras","Barcode")}</dt><dd><span class="tag">${esc(p.barcode||"—")}</span></dd><dt>${tr("Línea de producción","Production line")}</dt><dd>${p.line?esc(NV.L(LINES.find(l=>l.id===p.line).name)):"—"}</dd></dl></div>
      <div class="card card-b"><dl class="dl"><dt>${tr("Precio de venta (sin IVA)","Sale price (net)")}</dt><dd>${money(p.price,2)}</dd><dt>${tr("Precio con IVA","Price incl. VAT")}</dt><dd>${money(p.price*1.21,2)}</dd><dt>${tr("Costo","Cost")}</dt><dd>${money(p.cost,2)} ${bom?`<span class="muted small">(${tr("calculado por BOM","from BOM")})</span>`:""}</dd><dt>${tr("Stock mínimo","Minimum stock")}</dt><dd>${p.min?num(p.min)+" "+esc(p.unit):"—"}</dd><dt>${NV.t("desc")}</dt><dd>${esc(p.desc||"—")}</dd></dl></div></div>`;
    if(tab==="stock")b.innerHTML=`<div class="card card-b flush"><div class="tbl-w"><table class="t"><thead><tr><th>${tr("Almacén","Warehouse")}</th><th class="r">${tr("Cantidad","Quantity")}</th><th class="r">${tr("Valorizado","Value")}</th><th style="width:40%">${tr("Distribución","Share")}</th></tr></thead><tbody>${WH.map(w=>{const q=p.stock[w.id],tot=stockT(p)||1;return `<tr><td><b>${esc(NV.L(w.name))}</b><div class="small muted">${w.id} · ${w.loc}</div></td><td class="num">${num(q,q%1?2:0)} ${esc(p.unit)}</td><td class="num">${money(q*p.cost)}</td><td><div class="bar"><i style="width:${Math.max(0,q/tot*100)}%"></i></div></td></tr>`}).join("")}</tbody><tfoot><tr><td>${NV.t("total")}</td><td class="num">${num(stockT(p),2)} ${esc(p.unit)}</td><td class="num">${money(stockT(p)*p.cost)}</td><td>${p.min?(stockT(p)<p.min?badge(tr("Bajo mínimo","Below minimum"),"bad"):badge(tr("OK","OK"),"ok")):""}</td></tr></tfoot></table></div></div>`;
    if(tab==="bom")bomTable(b,bom);
    if(tab==="moves")table(b,{rows:db().moves.filter(x=>x.p===id),name:"movimientos",columns:moveCols(false)});
    if(tab==="sales")table(b,{rows:sold,name:"ventas",onRow:r=>NV.go("#/billing/invoice/"+r.inv.id),columns:[{k:"ref",label:NV.t("ref"),render:r=>`<span class="ref">${r.inv.ref}</span>`,text:r=>r.inv.ref},{k:"date",label:NV.t("date"),render:r=>date(r.inv.date),sv:r=>r.inv.date},{k:"tp",label:NV.t("customer"),render:r=>esc(TP(r.inv.tp).name),text:r=>TP(r.inv.tp).name},{k:"q",label:NV.t("qty"),r:1,render:r=>num(r.l.q),sv:r=>r.l.q},{k:"pr",label:NV.t("price"),r:1,render:r=>money(r.l.price,2)},{k:"am",label:NV.t("amount"),r:1,sv:r=>r.l.q*r.l.price,render:r=>money(r.l.q*r.l.price*(1-r.l.disc/100))}]});
  });
  $("[data-e]",main).onclick=()=>formModal({title:NV.t("edit"),fields:prodFields().filter(f=>f.k!=="id"),vals:{...p,nameEs:NV.L(p.name)},onSave:v=>{p.name=[v.nameEs,NV.lang==="en"?v.nameEs:p.name[1]];if(NV.lang==="en")p.name[1]=v.nameEs;Object.assign(p,{type:v.type,unit:v.unit,price:v.price,cost:v.cost,min:v.min,barcode:v.barcode,desc:v.desc});save();toast(NV.t("saved"));NV.render()}});
  bindActs(main);
}

/* ---------- stock ---------- */
const moveCols=(withP=true)=>[{k:"date",label:NV.t("date"),render:x=>date(x.date)},...(withP?[{k:"p",label:NV.t("product"),render:x=>pLink(x.p),text:x=>x.p+" "+pname(x.p)}]:[]),{k:"wh",label:tr("Almacén","Warehouse"),render:x=>esc(NV.L(WH.find(w=>w.id===x.wh).name)),text:x=>NV.L(WH.find(w=>w.id===x.wh).name)},{k:"label",label:tr("Concepto","Reason"),render:x=>esc(NV.L(x.label)),text:x=>NV.L(x.label)},{k:"origin",label:tr("Origen","Source"),render:x=>x.origin?`<span class="tag">${esc(x.origin)}</span>`:""},{k:"q",label:NV.t("qty"),r:1,render:x=>`<b class="${x.q<0?"down":"up"}">${x.q>0?"+":""}${num(x.q,x.q%1?2:0)}</b>`}];
function pageWarehouses(main){
  H(main,{crumbs:[["Stock","#/stock"]],icon:"warehouse",title:tr("Almacenes","Warehouses"),actions:`<button class="btn" data-a="transfer">${icon("move")}${tr("Transferir stock","Transfer stock")}</button><button class="btn pri" data-a="correct">${icon("edit")}${tr("Corregir stock","Adjust stock")}</button>`});
  const ps=db().products.filter(p=>p.type!=="SV");
  append(main,`<div class="g g3">${WH.map(w=>{const items=ps.filter(p=>p.stock[w.id]>0);const val=items.reduce((s,p)=>s+p.stock[w.id]*p.cost,0);return `<div class="card"><div class="card-h"><h3>${icon("warehouse")}${esc(NV.L(w.name))}</h3><span class="tag">${w.id}</span></div><div class="card-b"><dl class="dl"><dt>${tr("Ubicación","Location")}</dt><dd>${w.loc}</dd><dt>${tr("Productos con stock","Items in stock")}</dt><dd>${items.length}</dd><dt>${tr("Valorizado","Value")}</dt><dd>${money(val)}</dd></dl></div></div>`}).join("")}</div>`);
  const c=append(main,`<div class="card mt"><div class="card-h"><h3>${icon("chart")}${tr("Valor de inventario por almacén y tipo","Inventory value by warehouse and type")}</h3></div><div class="card-b"><div class="chart"><canvas></canvas></div></div></div>`);
  chart($("canvas",c),{type:"bar",money:true,stacked:true,data:{labels:WH.map(w=>NV.L(w.name)),datasets:["PT","SE","MP"].map(tp=>({label:NV.L(CATS[tp]),data:WH.map(w=>ps.filter(p=>p.type===tp).reduce((s,p)=>s+p.stock[w.id]*p.cost,0))}))}});
  append(main,`<h3 style="margin:22px 0 12px;font-size:15px">${tr("Últimos movimientos","Latest movements")}</h3>`);
  table(main,{rows:()=>db().moves.slice(0,40),name:"movimientos",pageSize:8,columns:moveCols()});
  bindActs(main);
}
function pageMoves(main){H(main,{crumbs:[["Stock","#/stock"]],icon:"move",title:tr("Movimientos de stock","Stock movements"),actions:`<button class="btn pri" data-a="correct">${icon("edit")}${tr("Corregir stock","Adjust stock")}</button>`});
  table(main,{rows:()=>db().moves,name:"movimientos",pageSize:15,filters:[{k:"wh",label:tr("Almacén","Warehouse"),options:WH.map(w=>[w.id,w.name])},{k:"label",label:tr("Concepto","Reason"),get:x=>NV.L(x.label),options:[...new Set(db().moves.map(m=>NV.L(m.label)))]}],columns:moveCols()});bindActs(main)}
function pageAlerts(main){H(main,{crumbs:[["Stock","#/stock"]],icon:"alert",title:tr("Alertas de stock","Stock alerts"),sub:tr("Productos por debajo del stock mínimo. Generá el pedido al proveedor con un clic.","Items below minimum stock. Create the purchase order in one click.")});
  table(main,{rows:()=>db().products.filter(p=>p.min&&stockT(p)<p.min),name:"alertas",onRow:x=>NV.go("#/products/card/"+x.id),
    columns:[{k:"id",label:NV.t("ref"),render:x=>`<span class="ref">${x.id}</span>`},{k:"name",label:NV.t("product"),render:x=>`<b>${esc(NV.L(x.name))}</b>`,text:x=>NV.L(x.name)},{k:"type",label:tr("Tipo","Type"),render:x=>esc(NV.L(CATS[x.type])),text:x=>NV.L(CATS[x.type])},{k:"st",label:"Stock",r:1,sv:x=>stockT(x),render:x=>`<b class="down">${num(stockT(x),1)}</b>`},{k:"min",label:tr("Mínimo","Minimum"),r:1,render:x=>num(x.min)},{k:"cov",label:tr("Cobertura","Coverage"),nosort:1,render:x=>{const c=Math.min(100,stockT(x)/x.min*100);return `<div class="bar ${c<40?"bad":"warn"}"><i style="width:${c}%"></i></div>`},nocsv:1},
      {k:"act",label:"",nosort:1,nocsv:1,render:x=>{if(x.type==="MP"){const s=db().tps.find(t=>t.kind==="supplier"&&(t.supplies||[]).includes(x.id));return s?`<button class="btn sm pri" data-po="${x.id}">${icon("truck")}${tr("Pedir","Order")}</button>`:""}return `<button class="btn sm" data-mo="${x.id}">${icon("factory")}${tr("Fabricar","Manufacture")}</button>`}}],
    after:w=>{$$("[data-po]",w).forEach(b=>b.onclick=()=>{const p=P(b.dataset.po);const s=db().tps.find(t=>t.kind==="supplier"&&(t.supplies||[]).includes(p.id));const doc={id:NV.uid("S"),ref:nextRef("CF"),tp:s.id,date:iso(TODAY),delivery:iso(addDays(TODAY,7)),lines:[{p:p.id,q:Math.ceil(p.min*2-stockT(p)),price:p.cost,disc:0}],status:"draft",notes:tr("Generado desde alertas de stock","Created from stock alerts"),origin:"",hist:[{d:iso(TODAY),txt:tr("Pedido creado desde alerta de stock","Order created from stock alert")}]};db().sorders.push(doc);save();toast(NV.t("created"));NV.go("#/purchases/order/"+doc.id)});
      $$("[data-mo]",w).forEach(b=>b.onclick=()=>newMO(b.dataset.mo))}});}
function pageValuation(main){H(main,{crumbs:[["Stock","#/stock"]],icon:"money",title:tr("Inventario valorizado","Inventory valuation"),sub:tr("Valorizado al costo (PMP).","Valued at weighted average cost.")});
  const rows=db().products.filter(p=>p.type!=="SV");
  table(main,{rows,name:"valorizado",pageSize:25,sort:"val",dir:-1,filters:[{k:"type",label:tr("Tipo","Type"),options:Object.entries(CATS).filter(c=>c[0]!=="SV")}],onRow:x=>NV.go("#/products/card/"+x.id),
    columns:[{k:"id",label:NV.t("ref"),render:x=>`<span class="ref">${x.id}</span>`},{k:"name",label:NV.t("product"),render:x=>esc(NV.L(x.name)),text:x=>NV.L(x.name)},...WH.map(w=>({k:w.id,label:w.id,r:1,sv:x=>x.stock[w.id],text:x=>x.stock[w.id],render:x=>num(x.stock[w.id],x.stock[w.id]%1?1:0)})),{k:"cost",label:tr("Costo","Cost"),r:1,render:x=>money(x.cost,2)},{k:"val",label:tr("Valorizado","Value"),r:1,sv:x=>stockT(x)*x.cost,text:x=>Math.round(stockT(x)*x.cost),render:x=>`<b>${money(stockT(x)*x.cost)}</b>`}],
    footer:all=>`<tr><td colspan="6">${NV.t("total")}</td><td></td><td class="num">${money(all.reduce((s,x)=>s+stockT(x)*x.cost,0))}</td></tr>`});}
function stockModal(mode,pid){const ps=db().products.filter(p=>p.type!=="SV");
  const fields=[{k:"p",label:NV.t("product"),type:"select",options:ps.map(p=>[p.id,p.id+" · "+NV.L(p.name)]),full:1,def:pid||ps[0].id},
    ...(mode==="transfer"?[{k:"from",label:tr("Desde","From"),type:"select",options:WH.map(w=>[w.id,w.name]),def:"W1"},{k:"to",label:tr("Hacia","To"),type:"select",options:WH.map(w=>[w.id,w.name]),def:"W2"}]:[{k:"wh",label:tr("Almacén","Warehouse"),type:"select",options:WH.map(w=>[w.id,w.name])},{k:"dir",label:tr("Tipo de ajuste","Adjustment"),type:"select",options:[["in",["Ingreso (+)","Add (+)"]],["out",["Egreso (−)","Remove (−)"]]]}]),
    {k:"q",label:NV.t("qty"),type:"number",req:1,step:"0.01",min:0},{k:"label",label:tr("Motivo","Reason"),def:mode==="transfer"?tr("Transferencia interna","Internal transfer"):tr("Ajuste por inventario físico","Physical count adjustment"),full:1}];
  formModal({title:mode==="transfer"?tr("Transferir stock","Transfer stock"):tr("Corregir stock","Adjust stock"),fields,onSave:v=>{if(!(v.q>0)){toast(NV.t("req_err"));return false}
    const ref="TR-"+Date.now().toString().slice(-5);
    if(mode==="transfer"){if(v.from===v.to){toast(tr("Elegí almacenes distintos","Choose different warehouses"));return false}if(P(v.p).stock[v.from]<v.q){toast(tr("No hay stock suficiente en el origen","Not enough stock at source"));return false}addMove(v.p,v.from,-v.q,[v.label,v.label],ref);addMove(v.p,v.to,v.q,[v.label,v.label],ref)}
    else addMove(v.p,v.wh,v.dir==="out"?-v.q:v.q,[v.label,v.label],ref);
    save();toast(tr("Stock actualizado","Stock updated"));NV.render()}})}

/* ---------- MRP ---------- */
function bomTable(host,bom){const p=P(bom.product);const mat=bom.comps.reduce((s,c)=>s+P(c.p).cost*c.q,0),lab=bom.hours*LABOR_RATE;
  const el=NV.el(`<div><div class="card card-b flush"><div class="tbl-w"><table class="t"><thead><tr><th>${tr("Componente","Component")}</th><th>${tr("Tipo","Type")}</th><th class="r">${tr("Cant. por unidad","Qty per unit")}</th><th class="r">${tr("Costo unit.","Unit cost")}</th><th class="r">${tr("Costo","Cost")}</th><th class="r">${tr("Stock disp.","Available")}</th></tr></thead><tbody>
    ${bom.comps.map(c=>{const cp=P(c.p);return `<tr><td>${pLink(c.p)}</td><td>${esc(NV.L(CATS[cp.type]))}</td><td class="num">${num(c.q,2)} ${esc(cp.unit)}</td><td class="num">${money(cp.cost,2)}</td><td class="num">${money(cp.cost*c.q,2)}</td><td class="num ${cp.min&&stockT(cp)<cp.min?"down":""}">${num(stockT(cp),1)}</td></tr>`}).join("")}
    <tr><td><b>${tr("Mano de obra","Labor")}</b> · ${esc(NV.L(LINES.find(l=>l.id===bom.line)?.name||"—"))}</td><td>${tr("Operación","Operation")}</td><td class="num">${num(bom.hours,2)} h</td><td class="num">${money(LABOR_RATE,2)}/h</td><td class="num">${money(lab,2)}</td><td></td></tr></tbody>
    <tfoot><tr><td colspan="4">${tr("Costo total por unidad","Total unit cost")}</td><td class="num">${money(mat+lab,2)}</td><td></td></tr></tfoot></table></div></div>
    <div class="g g3 mt">${NV.kpi("layers",tr("Materiales","Materials"),money(mat,2))}${NV.kpi("clock",tr("Mano de obra","Labor"),money(lab,2),"vio")}${NV.kpi("pie",tr("Margen sobre precio","Margin on price"),num((p.price-(mat+lab))/p.price*100,1)+"%","ok")}</div></div>`);host.appendChild(el)}
function pageBoms(main){H(main,{crumbs:[[tr("Fabricación","Manufacturing"),"#/mrp"]],icon:"layers",title:tr("Listas de materiales (BOM)","Bills of materials (BOM)"),sub:tr("Estructura de cada producto: componentes, cantidades y horas de línea.","Each product's structure: components, quantities and line hours.")});
  table(main,{rows:db().boms,name:"boms",onRow:x=>NV.go("#/mrp/bom/"+x.id),columns:[{k:"id",label:NV.t("ref"),render:x=>`<span class="ref">${x.id}</span>`},{k:"product",label:NV.t("product"),render:x=>pLink(x.product),text:x=>pname(x.product)},{k:"n",label:tr("Componentes","Components"),r:1,sv:x=>x.comps.length,render:x=>x.comps.length},{k:"hours",label:tr("Horas/u","Hours/unit"),r:1,render:x=>num(x.hours,2)},{k:"line",label:tr("Línea","Line"),render:x=>esc(NV.L(LINES.find(l=>l.id===x.line)?.name||"—")),text:x=>NV.L(LINES.find(l=>l.id===x.line)?.name||"")},{k:"cost",label:tr("Costo/u","Unit cost"),r:1,sv:x=>P(x.product).cost,render:x=>money(P(x.product).cost,2)},{k:"st",label:NV.t("status"),render:()=>badge(tr("Activa","Active"),"ok"),nocsv:1}]})}
function pageBom(main,{id}){const b=db().boms.find(x=>x.id===id);if(!b)return notFound(main);H(main,{crumbs:[[tr("Fabricación","Manufacturing"),"#/mrp"],["BOM","#/mrp/boms"],b.id],icon:"layers",title:"BOM · "+pname(b.product),sub:`<span class="ref">${b.id}</span>`,actions:`<button class="btn pri" data-a="newMO" data-p="${b.product}">${icon("factory")}${tr("Crear orden de fabricación","Create manufacturing order")}</button>`});bomTable(main,b);bindActs(main)}
function pageMOs(main){H(main,{crumbs:[[tr("Fabricación","Manufacturing"),"#/mrp"]],icon:"factory",title:tr("Órdenes de fabricación","Manufacturing orders"),actions:`<button class="btn pri" data-a="newMO">${icon("plus")}${tr("Nueva OF","New MO")}</button>`});
  const d=db();append(main,`<div class="g g4">${NV.kpi("factory",tr("En curso","In progress"),d.mos.filter(m=>m.status==="inprogress").length,"warn")}${NV.kpi("clock",tr("Por iniciar","To start"),d.mos.filter(m=>m.status==="validated"||m.status==="draft").length)}${NV.kpi("check",tr("Finalizadas (30 días)","Done (30 days)"),d.mos.filter(m=>m.status==="done"&&daysBetween(m.end,iso(TODAY))<=30).length,"ok")}${NV.kpi("box",tr("Unidades producidas (30 días)","Units produced (30 days)"),num(d.moves.filter(x=>x.label[0]==="Producción"&&daysBetween(x.date,iso(TODAY))<=30).reduce((s,x)=>s+x.q,0)),"vio")}</div><div class="mt"></div>`);
  table(main,{rows:()=>db().mos.slice().reverse(),name:"ordenes_fabricacion",onRow:x=>NV.go("#/mrp/mo/"+x.id),filters:[{k:"status",label:NV.t("status"),options:stOpts("mo")},{k:"line",label:tr("Línea","Line"),options:LINES.map(l=>[l.id,l.name])}],
    columns:[{k:"ref",label:NV.t("ref"),render:x=>`<span class="ref">${x.ref}</span>`},{k:"product",label:NV.t("product"),render:x=>`${esc(pname(x.product))}<div class="small muted">${x.product}</div>`,text:x=>pname(x.product)},{k:"line",label:tr("Línea","Line"),render:x=>esc(NV.L(LINES.find(l=>l.id===x.line)?.name||"—")),text:x=>NV.L(LINES.find(l=>l.id===x.line)?.name||"")},{k:"start",label:tr("Inicio","Start"),render:x=>date(x.start)},{k:"end",label:tr("Fin previsto","Planned end"),render:x=>`<span class="${x.status!=="done"&&x.status!=="canceled"&&D2(x.end)<TODAY?"down strong":""}">${date(x.end)}</span>`},
      {k:"qty",label:tr("Avance","Progress"),sv:x=>x.produced/x.qty,text:x=>x.produced+"/"+x.qty,render:x=>`<div style="min-width:120px"><div class="small"><b>${num(x.produced)}</b> / ${num(x.qty)}</div><div class="bar ${x.status==="done"?"ok":""}"><i style="width:${x.produced/x.qty*100}%"></i></div></div>`},{k:"status",label:NV.t("status"),render:x=>stBadge("mo",x.status),text:x=>NV.L(ST.mo[x.status][0])}]});bindActs(main)}
function moNeeds(mo){const b=BOMS[mo.product];return b[0].map(([c,q])=>{const cp=P(c);const need=q*mo.qty,left=q*(mo.qty-mo.produced);return {c,cp,q,need,left,avail:cp.stock.W1+cp.stock.W2}})}
function maxProducible(mo){return Math.max(0,Math.min(mo.qty-mo.produced,...moNeeds(mo).map(n=>Math.floor((n.cp.stock.W1+n.cp.stock.W2)/n.q))))}
function pageMO(main,{id}){const mo=db().mos.find(m=>m.id===id);if(!mo)return notFound(main);const p=P(mo.product);
  const acts=[];if(mo.status==="draft")acts.push(`<button class="btn pri" data-mo="validate">${icon("check")}${tr("Validar","Validate")}</button>`);
  if(mo.status==="validated")acts.push(`<button class="btn pri" data-mo="start">${icon("play")}${tr("Iniciar producción","Start production")}</button>`);
  if(mo.status==="inprogress")acts.push(`<button class="btn pri" data-mo="produce">${icon("factory")}${tr("Declarar producción","Record production")}</button>`);
  if(["draft","validated","inprogress"].includes(mo.status))acts.push(`<button class="btn bad" data-mo="cancel">${icon("x")}${tr("Cancelar","Cancel")}</button>`);
  H(main,{crumbs:[[tr("Fabricación","Manufacturing"),"#/mrp"],mo.ref],icon:"factory",title:mo.ref+" · "+pname(mo.product),sub:stBadge("mo",mo.status),actions:acts.join("")});
  const steps=["draft","validated","inprogress","done"];const si=steps.indexOf(mo.status);
  append(main,`<div class="steps">${steps.map((s,i)=>`<span class="${i<si?"done":i===si?"on":""}">${esc(NV.L(ST.mo[s][0]))}</span>`).join("")}</div>`);
  const pc=mo.produced/mo.qty*100;
  append(main,`<div class="g g-2-1"><div class="card card-b"><dl class="dl"><dt>${NV.t("product")}</dt><dd>${pLink(mo.product)}</dd><dt>${tr("Cantidad a producir","Quantity to produce")}</dt><dd>${num(mo.qty)} ${esc(p.unit)}</dd><dt>${tr("Producido","Produced")}</dt><dd>${num(mo.produced)} ${esc(p.unit)}<div class="bar" style="margin-top:6px;max-width:260px"><i style="width:${pc}%"></i></div></dd><dt>${tr("Línea","Line")}</dt><dd>${esc(NV.L(LINES.find(l=>l.id===mo.line)?.name||"—"))}</dd><dt>${tr("Inicio","Start")}</dt><dd>${date(mo.start)}</dd><dt>${tr("Fin previsto","Planned end")}</dt><dd>${date(mo.end)}</dd><dt>${tr("Origen","Source")}</dt><dd>${mo.origin?`<span class="tag">${esc(mo.origin)}</span>`:"—"}</dd><dt>${tr("Almacén destino","Destination")}</dt><dd>${esc(NV.L(WH[2].name))}</dd></dl></div>
   <div class="card"><div class="card-h"><h3>${icon("clock")}${tr("Historial","History")}</h3></div><div class="card-b"><ul class="tl">${mo.hist.slice().reverse().map(h=>`<li><span class="tic">${icon("factory")}</span><div><b>${esc(h.txt)}</b><p>${date(h.d)}</p></div></li>`).join("")}</ul></div></div></div>`);
  append(main,`<h3 style="margin:22px 0 12px;font-size:15px">${tr("Consumo de componentes","Component consumption")}</h3>`);
  append(main,`<div class="card"><div class="tbl-w"><table class="t"><thead><tr><th>${tr("Componente","Component")}</th><th class="r">${tr("Por unidad","Per unit")}</th><th class="r">${tr("Total requerido","Total required")}</th><th class="r">${tr("Consumido","Consumed")}</th><th class="r">${tr("Pendiente","Remaining")}</th><th class="r">${tr("Disponible (W1+W2)","Available (W1+W2)")}</th><th>${NV.t("status")}</th></tr></thead><tbody>${moNeeds(mo).map(n=>`<tr><td>${pLink(n.c)}</td><td class="num">${num(n.q,2)}</td><td class="num">${num(n.need,2)} ${esc(n.cp.unit)}</td><td class="num">${num(n.need-n.left,2)}</td><td class="num">${num(n.left,2)}</td><td class="num">${num(n.avail,2)}</td><td>${n.avail>=n.left?badge(tr("Disponible","Available"),"ok"):badge(tr("Faltante","Shortage"),"bad")}</td></tr>`).join("")}</tbody></table></div></div>`);
  $$("[data-mo]",main).forEach(b=>b.onclick=()=>{const a=b.dataset.mo;
    if(a==="validate"){mo.status="validated";mo.hist.push({d:iso(TODAY),txt:tr("Orden validada","Order validated")});save();toast(NV.t("saved"));NV.render()}
    if(a==="start"){mo.status="inprogress";mo.hist.push({d:iso(TODAY),txt:tr("Producción iniciada en línea","Production started on line")});save();toast(NV.t("saved"));NV.render()}
    if(a==="cancel")confirmBox(tr("¿Cancelar esta orden de fabricación?","Cancel this manufacturing order?"),()=>{mo.status="canceled";mo.hist.push({d:iso(TODAY),txt:tr("Orden cancelada","Order canceled")});save();NV.render()});
    if(a==="produce"){const mx=maxProducible(mo);formModal({title:tr("Declarar producción","Record production"),fields:[{k:"q",label:tr(`Cantidad producida (máx. ${mx} con stock actual)`,`Quantity produced (max ${mx} with current stock)`),type:"number",def:mx,min:1,req:1}],onSave:v=>{const q=Math.min(Number(v.q),mx);if(!(q>0)){toast(tr("No hay componentes suficientes. Revisá las alertas de stock.","Not enough components. Check stock alerts."));return false}
      moNeeds(mo).forEach(n=>{let need=Math.round(n.q*q*100)/100;const fromW2=Math.min(need,n.cp.stock.W2);if(fromW2>0)addMove(n.c,"W2",-fromW2,["Consumo de producción","Production consumption"],mo.ref);need-=fromW2;if(need>0)addMove(n.c,"W1",-need,["Consumo de producción","Production consumption"],mo.ref)});
      addMove(mo.product,"W3",q,["Producción","Production"],mo.ref);mo.produced+=q;mo.hist.push({d:iso(TODAY),txt:tr(`Producción declarada: ${q} u`,`Production recorded: ${q} units`)});
      if(mo.produced>=mo.qty){mo.status="done";mo.hist.push({d:iso(TODAY),txt:tr("Orden finalizada","Order completed")})}save();toast(tr("Producción registrada y stock actualizado","Production recorded and stock updated"));NV.render()}})}
  });}
function newMO(pid){const ps=db().boms.map(b=>P(b.product));formModal({title:tr("Nueva orden de fabricación","New manufacturing order"),fields:[{k:"p",label:NV.t("product"),type:"select",options:ps.map(p=>[p.id,p.id+" · "+NV.L(p.name)]),def:pid||ps[0].id,full:1},{k:"qty",label:tr("Cantidad","Quantity"),type:"number",req:1,def:20,min:1},{k:"start",label:tr("Fecha de inicio","Start date"),type:"date",def:iso(TODAY)},{k:"origin",label:tr("Origen (pedido)","Source (order)"),type:"select",options:[["","—"]].concat(db().orders.filter(o=>o.status!=="billed").map(o=>[o.ref,o.ref+" · "+TP(o.tp).name]))}],
  onSave:v=>{const p=P(v.p);const mo={id:NV.uid("M"),ref:nextRef("MO"),product:v.p,qty:Number(v.qty),produced:0,status:"draft",start:v.start,end:iso(addDays(v.start,Math.ceil(v.qty*BOMS[v.p][1]/16)+1)),line:p.line,origin:v.origin,hist:[{d:iso(TODAY),txt:tr("Orden de fabricación creada","Manufacturing order created")}]};db().mos.push(mo);save();toast(NV.t("created"));NV.go("#/mrp/mo/"+mo.id)}})}
function pageCapacity(main){H(main,{crumbs:[[tr("Fabricación","Manufacturing"),"#/mrp"]],icon:"chart",title:tr("Planificación y capacidad","Planning & capacity"),sub:tr("Horas de línea comprometidas por órdenes abiertas vs. capacidad semanal (2 turnos × 8 h × 5 días = 80 h).","Line hours committed by open orders vs weekly capacity (2 shifts × 8 h × 5 days = 80 h).")});
  const open=db().mos.filter(m=>["draft","validated","inprogress"].includes(m.status));
  const load=LINES.map(l=>open.filter(m=>m.line===l.id).reduce((s,m)=>s+(m.qty-m.produced)*BOMS[m.product][1],0));
  const c=append(main,`<div class="g g-2-1"><div class="card"><div class="card-h"><h3>${icon("chart")}${tr("Carga por línea (horas)","Load by line (hours)")}</h3></div><div class="card-b"><div class="chart"><canvas></canvas></div></div></div><div class="card"><div class="card-h"><h3>${icon("factory")}${tr("Ocupación","Utilization")}</h3></div><ul class="list-mini">${LINES.map((l,i)=>{const u=load[i]/80*100;return `<li><div style="flex:1"><b>${esc(NV.L(l.name))}</b><div class="bar ${u>100?"bad":u>80?"warn":""}" style="margin-top:6px"><i style="width:${Math.min(100,u)}%"></i></div></div><span class="num small"><b>${num(u)}%</b><br>${num(load[i],1)} h</span></li>`}).join("")}</ul></div></div>`);
  chart($("canvas",c),{type:"bar",data:{labels:LINES.map(l=>NV.L(l.name)),datasets:[{label:tr("Horas comprometidas","Committed hours"),data:load.map(x=>Math.round(x))},{type:"line",label:tr("Capacidad semanal","Weekly capacity"),data:LINES.map(()=>80),color:"#D93A3A",pointRadius:0}]}});
  append(main,`<h3 style="margin:22px 0 12px;font-size:15px">${tr("Cronograma de órdenes abiertas","Open orders timeline")}</h3>`);
  const min=open.reduce((m,x)=>x.start<m?x.start:m,iso(TODAY)),max=open.reduce((m,x)=>x.end>m?x.end:m,iso(addDays(TODAY,7)));const span=Math.max(1,daysBetween(min,max));
  append(main,`<div class="card card-b">${open.map(m=>{const l=daysBetween(min,m.start)/span*100,w=Math.max(3,daysBetween(m.start,m.end)/span*100);return `<div style="display:grid;grid-template-columns:minmax(150px,220px) 1fr;gap:12px;align-items:center;padding:6px 0;border-bottom:1px solid var(--line-2)"><div class="small"><a class="ref" href="#/mrp/mo/${m.id}">${m.ref}</a><div class="muted" style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(pname(m.product))}</div></div><div style="position:relative;height:22px;background:var(--surface-2);border-radius:6px"><div title="${date(m.start)} → ${date(m.end)}" style="position:absolute;left:${l}%;width:${Math.min(w,100-l)}%;top:3px;bottom:3px;border-radius:5px;background:${m.status==="inprogress"?"linear-gradient(90deg,var(--warn),#FFC861)":"linear-gradient(90deg,var(--blue),var(--blue-2))"}"></div></div></div>`}).join("")||`<div class="empty">—</div>`}<div class="small muted" style="display:flex;justify-content:space-between;margin-top:8px"><span>${date(min)}</span><span>${date(max)}</span></div></div>`);}

/* ---------- documents (quotes, orders, invoices, purchase docs) ---------- */
function docList(main,kind,{filterFn,title}={}){const K=KIND[kind];
  H(main,{crumbs:[[NV.L(K.many),K.list]],icon:K.icon,title:title||NV.L(K.many),actions:`<button class="btn pri" data-new="${kind}">${icon("plus")}${tr("Nuevo","New")}</button>`});
  const rows=()=>db()[K.coll].filter(filterFn||(()=>true)).slice().sort((a,b)=>b.date.localeCompare(a.date));
  const all=rows();const tot=all.reduce((s,x)=>s+calc(x).ht,0);
  if(kind==="invoice"||kind==="sinvoice"){const rest=all.reduce((s,x)=>s+calc(x).rest,0),ov=all.filter(x=>payStatus(x)==="overdue").reduce((s,x)=>s+calc(x).rest,0);append(main,`<div class="g g3" style="margin-bottom:16px">${NV.kpi("invoice",tr("Total facturado (sin IVA)","Total billed (net)"),money(tot))}${NV.kpi("clock",tr("Pendiente de pago","Outstanding"),money(rest),"warn")}${NV.kpi("alert",tr("Vencido","Overdue"),money(ov),"bad")}</div>`)}
  else append(main,`<div class="g g3" style="margin-bottom:16px">${NV.kpi(K.icon,tr("Documentos","Documents"),num(all.length))}${NV.kpi("money",tr("Monto total (sin IVA)","Total amount (net)"),money(tot),"vio")}${NV.kpi("clock",tr("Pendientes","Pending"),num(all.filter(x=>!["billed","received","notsigned"].includes(x.status)).length),"warn")}</div>`);
  table(main,{rows,name:K.coll,onRow:x=>NV.go("#/"+K.base+"/"+x.id),filters:[{k:"st",label:NV.t("status"),get:x=>stKey(kind,x),options:stOpts(kind)},{k:"tp",label:NV.L(K.tp==="supplier"?["Proveedor","Supplier"]:["Cliente","Customer"]),options:[...new Set(all.map(x=>x.tp))].map(id=>[id,TP(id).name]).sort((a,b)=>a[1].localeCompare(b[1]))}],
    columns:[{k:"ref",label:NV.t("ref"),render:x=>`<span class="ref">${x.ref}</span>${x.supref?`<div class="small muted">${x.supref}</div>`:""}`},{k:"tp",label:NV.L(K.tp==="supplier"?["Proveedor","Supplier"]:["Cliente","Customer"]),render:x=>`<b>${esc(TP(x.tp).name)}</b>`,text:x=>TP(x.tp).name,sv:x=>TP(x.tp).name},{k:"date",label:NV.t("date"),render:x=>date(x.date)},
      ...(kind==="invoice"||kind==="sinvoice"?[{k:"due",label:tr("Vencimiento","Due"),render:x=>`<span class="${payStatus(x)==="overdue"?"down strong":""}">${date(x.due)}</span>`}]:kind==="quote"?[{k:"valid",label:tr("Válido hasta","Valid until"),render:x=>date(x.valid)}]:[{k:"delivery",label:tr("Entrega","Delivery"),render:x=>date(x.delivery)}]),
      {k:"ht",label:tr("Neto","Net"),r:1,sv:x=>calc(x).ht,text:x=>calc(x).ht.toFixed(2),render:x=>money(calc(x).ht,2)},{k:"ttc",label:tr("Total c/IVA","Total incl. VAT"),r:1,sv:x=>calc(x).ttc,text:x=>calc(x).ttc.toFixed(2),render:x=>`<b>${money(calc(x).ttc,2)}</b>`},
      ...(kind==="invoice"||kind==="sinvoice"?[{k:"rest",label:tr("Saldo","Balance"),r:1,sv:x=>calc(x).rest,text:x=>calc(x).rest.toFixed(2),render:x=>{const r=calc(x).rest;return r>.01?money(r,2):"<span class='muted'>0</span>"}}]:[]),
      {k:"st",label:NV.t("status"),sv:x=>stKey(kind,x),text:x=>NV.L(ST[kind][stKey(kind,x)][0]),render:x=>stBadge(kind,stKey(kind,x))}],
    footer:a=>`<tr><td colspan="4">${NV.t("total")} (${a.length})</td><td class="num">${money(a.reduce((s,x)=>s+calc(x).ht,0),2)}</td><td class="num">${money(a.reduce((s,x)=>s+calc(x).ttc,0),2)}</td>${kind==="invoice"||kind==="sinvoice"?`<td class="num">${money(a.reduce((s,x)=>s+calc(x).rest,0),2)}</td>`:""}<td></td></tr>`});
  $("[data-new]",main).onclick=()=>newDoc(kind);}
function newDoc(kind,tpId){const K=KIND[kind];const opts=db().tps.filter(t=>K.tp==="supplier"?t.kind==="supplier":t.kind!=="supplier").map(t=>[t.id,t.name]).sort((a,b)=>a[1].localeCompare(b[1]));
  formModal({title:tr("Nuevo","New")+" · "+NV.L(K.one),fields:[{k:"tp",label:NV.L(K.tp==="supplier"?["Proveedor","Supplier"]:["Cliente","Customer"]),type:"select",options:opts,def:tpId||opts[0][0],full:1,req:1},{k:"date",label:NV.t("date"),type:"date",def:iso(TODAY)},...(kind==="sinvoice"?[{k:"supref",label:tr("N° factura proveedor","Supplier invoice no."),ph:"A-0001-00012345"}]:[]),{k:"notes",label:NV.t("notes"),type:"textarea",full:1}],
   onSave:v=>{const t=TP(v.tp);const doc={id:NV.uid(kind[0].toUpperCase()),ref:nextRef(K.pre),tp:v.tp,date:v.date,lines:[],status:kind==="sinvoice"?"unpaid":"draft",notes:v.notes,origin:"",payments:[],hist:[{d:iso(TODAY),txt:tr("Documento creado","Document created")}]};
    if(kind==="invoice"||kind==="sinvoice")doc.due=iso(addDays(v.date,t.terms||30));if(kind==="quote")doc.valid=iso(addDays(v.date,30));if(kind==="order"||kind==="sorder")doc.delivery=iso(addDays(v.date,15));if(v.supref)doc.supref=v.supref;
    if(kind==="sorder"&&t.supplies&&t.supplies.length)doc.lines=t.supplies.map(p=>({p,q:P(p).min,price:P(p).cost,disc:0}));
    db()[K.coll].push(doc);save();toast(NV.t("created"));NV.go("#/"+K.base+"/"+doc.id)}})}
function copyDoc(src,toKind,status){const K=KIND[toKind];const t=TP(src.tp);const d={id:NV.uid(toKind[0].toUpperCase()),ref:nextRef(K.pre),tp:src.tp,date:iso(TODAY),lines:JSON.parse(JSON.stringify(src.lines)),status:status||"draft",notes:"",origin:src.ref,payments:[],hist:[{d:iso(TODAY),txt:tr("Creado desde ","Created from ")+src.ref}]};
  if(toKind==="invoice"||toKind==="sinvoice")d.due=iso(addDays(TODAY,t.terms||30));if(toKind==="order")d.delivery=iso(addDays(TODAY,15));db()[K.coll].push(d);return d}
function payModal(kind,doc){const c=calc(doc);formModal({title:tr("Registrar pago","Record payment")+" · "+doc.ref,fields:[{k:"amount",label:tr("Importe (US$)","Amount (US$)"),type:"number",step:"0.01",def:c.rest.toFixed(2),req:1},{k:"date",label:NV.t("date"),type:"date",def:iso(TODAY)},{k:"method",label:tr("Medio de pago","Method"),type:"select",options:["Transferencia","E-cheq","Cheque",tr("Efectivo","Cash")]},{k:"acc",label:tr("Cuenta","Account"),type:"select",options:db().banks.map(b=>[b.id,b.name])}],
  onSave:v=>{const a=Math.min(Number(v.amount),c.rest);if(!(a>0))return false;doc.payments.push({date:v.date,amount:Math.round(a*100)/100,method:v.method,acc:v.acc});db().btx.push({id:NV.uid("X"),date:v.date,acc:v.acc,amount:kind==="invoice"?a:-a,label:(kind==="invoice"?tr("Cobro ","Collection "):tr("Pago ","Payment "))+doc.ref,ref:doc.ref,cat:kind==="invoice"?"in":"supplier"});doc.hist.push({d:v.date,txt:tr("Pago registrado: ","Payment recorded: ")+money(a,2)});save();toast(tr("Pago registrado","Payment recorded"));NV.render()}})}
function docPrint(kind,doc){const K=KIND[kind],t=TP(doc.tp),c=calc(doc),co=db().company;
  modal({title:NV.t("print")+" · "+doc.ref,wide:true,body:`<div class="doc"><div class="dh2"><div><img src="../logo/nuvaryn-logo.svg" alt="" style="display:none"><h2>${esc(co.name)}</h2><div>${esc(co.address)}<br>CUIT ${co.cuit} · IVA Responsable Inscripto<br>${esc(co.email)} · ${co.phone}</div></div><div style="text-align:right"><h2>${esc(NV.L(K.one))}</h2><div style="font:700 15px var(--f-mono);color:#1466EF">${doc.ref}</div><div>${NV.t("date")}: ${date(doc.date)}</div>${doc.due?`<div>${tr("Vencimiento","Due")}: ${date(doc.due)}</div>`:""}${doc.valid?`<div>${tr("Válido hasta","Valid until")}: ${date(doc.valid)}</div>`:""}</div></div>
   <div class="parties"><div class="box"><small>${tr("Emisor","From")}</small><b>${esc(co.name)}</b><br>${esc(co.address)}</div><div class="box"><small>${NV.L(K.tp==="supplier"?["Proveedor","Supplier"]:["Cliente","Bill to"])}</small><b>${esc(t.name)}</b><br>CUIT ${esc(t.cuit||"")}<br>${esc(t.address||"")} · ${esc(t.city||"")}, ${esc(t.prov||"")}<br>${tr("Condición","Terms")}: ${t.terms||30} ${tr("días","days")}</div></div>
   <table><thead><tr><th>${NV.t("ref")}</th><th>${NV.t("desc")}</th><th style="text-align:right">${NV.t("qty")}</th><th style="text-align:right">${NV.t("price")}</th><th style="text-align:right">${NV.t("disc")}</th><th style="text-align:right">${NV.t("amount")}</th></tr></thead><tbody>${doc.lines.map(l=>`<tr><td>${l.p}</td><td>${esc(l.label||pname(l.p))}</td><td style="text-align:right">${num(l.q,l.q%1?2:0)}</td><td style="text-align:right">${money(l.price,2)}</td><td style="text-align:right">${l.disc?l.disc+"%":""}</td><td style="text-align:right">${money(l.q*l.price*(1-l.disc/100),2)}</td></tr>`).join("")}</tbody></table>
   <div class="tot"><div><span>${NV.t("subtotal")}</span><span>${money(c.ht,2)}</span></div><div><span>${NV.t("tax")}</span><span>${money(c.tax,2)}</span></div><div class="g"><span>${NV.t("total")}</span><span>${money(c.ttc,2)}</span></div>${c.paid?`<div><span>${tr("Pagado","Paid")}</span><span>${money(c.paid,2)}</span></div><div><b>${tr("Saldo","Balance")}</b><b>${money(c.rest,2)}</b></div>`:""}</div>
   <div class="foot">${kind==="invoice"?"CAE 76412398765432 · Vto. CAE "+date(addDays(doc.date,10))+" · ":""}${tr("Documento de ejemplo generado por Nuvaryn ERP. Datos ficticios.","Sample document generated by Nuvaryn ERP. Fictitious data.")}</div></div>`});}
function pageDoc(main,kind,{id}){const K=KIND[kind];const doc=db()[K.coll].find(x=>x.id===id);if(!doc)return notFound(main);
  const t=TP(doc.tp),c=calc(doc),sk=stKey(kind,doc),editable=doc.status==="draft"||(kind==="sinvoice"&&!doc.payments.length);
  const A=[];const add=(k,label,ic,cls="")=>A.push(`<button class="btn ${cls}" data-act="${k}">${icon(ic)}${esc(label)}</button>`);
  if(kind==="quote"){if(doc.status==="draft")add("validate",tr("Validar y enviar","Validate & send"),"send","pri");if(doc.status==="open"){add("sign",tr("Marcar firmado","Mark signed"),"check","pri");add("nosign",tr("No firmado","Not signed"),"x","bad")}if(doc.status==="signed"){add("toOrder",tr("Crear pedido","Create order"),"cart","pri");add("toInvoice",tr("Facturar","Invoice"),"invoice")}}
  if(kind==="order"){if(doc.status==="draft")add("validate",tr("Validar","Validate"),"check","pri");if(doc.status==="validated"){add("prep",tr("Iniciar preparación","Start picking"),"box","pri");add("toMO",tr("Crear OF","Create MO"),"factory")}if(doc.status==="inprocess")add("ship",tr("Despachar","Ship"),"truck","pri");if(["validated","inprocess","shipped"].includes(doc.status))add("toInvoice",tr("Facturar","Invoice"),"invoice",doc.status==="shipped"?"pri":"")}
  if(kind==="invoice"){if(doc.status==="draft")add("validate",tr("Validar factura","Validate invoice"),"check","pri");if(["unpaid","partial","overdue"].includes(sk))add("pay",tr("Registrar cobro","Record payment"),"money","pri")}
  if(kind==="sorder"){if(doc.status==="draft")add("approve",tr("Aprobar","Approve"),"check","pri");if(doc.status==="approved")add("send",tr("Enviar al proveedor","Send to supplier"),"send","pri");if(doc.status==="ordered")add("receive",tr("Recibir mercadería","Receive goods"),"warehouse","pri");if(doc.status==="received")add("toSinvoice",tr("Cargar factura","Record invoice"),"invoice")}
  if(kind==="sinvoice"&&sk!=="paid")add("pay",tr("Registrar pago","Record payment"),"money","pri");
  add("print",NV.t("print"),"printer");if(editable)add("del",NV.t("del"),"trash","bad");
  H(main,{crumbs:[[NV.L(K.many),K.list],doc.ref],icon:K.icon,title:doc.ref,sub:esc(NV.L(K.one))+" · "+stBadge(kind,sk),actions:A.join("")});
  const si=K.steps.indexOf(sk==="partial"||sk==="overdue"?"unpaid":sk);
  if(!(kind==="quote"&&doc.status==="notsigned"))append(main,`<div class="steps">${K.steps.map((s,i)=>`<span class="${i<si?"done":i===si?"on":""}">${esc(NV.L(ST[kind][s][0]))}</span>`).join("")}</div>`);
  const linked=[].concat(...Object.entries(KIND).map(([k,KK])=>db()[KK.coll].filter(x=>x.origin===doc.ref||x.ref===doc.origin).map(x=>[k,x]))).concat(db().mos.filter(m=>m.origin===doc.ref).map(m=>["mo",m]));
  append(main,`<div class="g g-2-1"><div class="card card-b"><dl class="dl"><dt>${NV.L(K.tp==="supplier"?["Proveedor","Supplier"]:["Cliente","Customer"])}</dt><dd>${tpLink(doc.tp)}</dd><dt>${NV.t("date")}</dt><dd>${date(doc.date)}</dd>${doc.due?`<dt>${tr("Vencimiento","Due date")}</dt><dd class="${sk==="overdue"?"down":""}">${date(doc.due)} ${sk==="overdue"?`(${daysBetween(doc.due,iso(TODAY))} ${tr("días de atraso","days overdue")})`:""}</dd>`:""}${doc.valid?`<dt>${tr("Válido hasta","Valid until")}</dt><dd>${date(doc.valid)}</dd>`:""}${doc.delivery?`<dt>${tr("Fecha de entrega","Delivery date")}</dt><dd>${date(doc.delivery)}</dd>`:""}${doc.supref?`<dt>${tr("N° proveedor","Supplier no.")}</dt><dd><span class="tag">${esc(doc.supref)}</span></dd>`:""}<dt>${tr("Condición de pago","Payment terms")}</dt><dd>${t.terms||30} ${tr("días","days")}</dd><dt>${tr("Vendedor","Sales rep")}</dt><dd>${esc(t.rep||"—")}</dd><dt>${tr("Origen","Source")}</dt><dd>${doc.origin?`<span class="tag">${esc(doc.origin)}</span>`:"—"}</dd><dt>${NV.t("notes")}</dt><dd>${esc(doc.notes||"—")}</dd></dl></div>
   <div style="display:flex;flex-direction:column;gap:16px"><div class="card card-b"><div class="doc" style="padding:0;box-shadow:none;background:transparent;color:inherit"><div class="tot" style="width:100%;margin:0"><div><span>${NV.t("subtotal")}</span><span>${money(c.ht,2)}</span></div><div><span>${NV.t("tax")}</span><span>${money(c.tax,2)}</span></div><div class="g" style="border-color:var(--ink)"><span>${NV.t("total")}</span><span>${money(c.ttc,2)}</span></div>${doc.payments?`<div><span>${tr("Pagado","Paid")}</span><span class="up">${money(c.paid,2)}</span></div><div><b>${tr("Saldo","Balance")}</b><b class="${c.rest>.01?"down":""}">${money(c.rest,2)}</b></div>`:""}</div></div></div>
   ${linked.length?`<div class="card"><div class="card-h"><h3>${icon("copy")}${tr("Documentos vinculados","Linked documents")}</h3></div><ul class="list-mini">${linked.map(([k,x])=>`<li><a class="ref" href="#/${k==="mo"?"mrp/mo":KIND[k].base}/${x.id}">${x.ref}</a><span class="small muted">${k==="mo"?tr("Orden de fabricación","Manufacturing order"):esc(NV.L(KIND[k].one))}</span></li>`).join("")}</ul></div>`:""}</div></div>`);
  // lines
  append(main,`<h3 style="margin:22px 0 12px;font-size:15px;display:flex;justify-content:space-between;align-items:center">${tr("Líneas","Lines")}${editable?`<span class="small muted" style="font-weight:500">${tr("Editable mientras esté en borrador","Editable while in draft")}</span>`:""}</h3>`);
  const lw=append(main,`<div class="card"><div class="tbl-w"></div></div>`);
  const saleable=db().products.filter(p=>K.tp==="supplier"?(p.type==="MP"||p.type==="SV"):(p.type==="PT"||p.type==="SV"||p.type==="SE"));
  function drawLines(){const cc=calc(doc);$(".tbl-w",lw).innerHTML=`<table class="t lines"><thead><tr><th>${NV.t("product")}</th><th class="r">${NV.t("qty")}</th><th class="r">${NV.t("price")}</th><th class="r">${NV.t("disc")}</th><th class="r">${NV.t("amount")}</th>${editable?"<th></th>":""}</tr></thead><tbody>
    ${doc.lines.map((l,i)=>editable?`<tr><td><select class="inp xs" data-l="${i}" data-f="p" style="min-width:220px">${saleable.map(p=>`<option value="${p.id}" ${p.id===l.p?"selected":""}>${p.id} · ${esc(NV.L(p.name))}</option>`).join("")}</select></td><td class="r"><input class="inp xs num" type="number" min="0" step="any" data-l="${i}" data-f="q" value="${l.q}" style="width:80px"></td><td class="r"><input class="inp xs num" type="number" step="0.01" data-l="${i}" data-f="price" value="${l.price}" style="width:100px"></td><td class="r"><input class="inp xs num" type="number" min="0" max="100" data-l="${i}" data-f="disc" value="${l.disc||0}" style="width:64px"></td><td class="num strong">${money(l.q*l.price*(1-(l.disc||0)/100),2)}</td><td><button class="ibtn" data-rm="${i}" aria-label="${NV.t("del")}">${icon("trash")}</button></td></tr>`
      :`<tr><td>${pLink(l.p)}${l.label?`<div class="small muted">${esc(l.label)}</div>`:""}</td><td class="num">${num(l.q,l.q%1?2:0)} <span class="muted small">${esc(P(l.p)?.unit||"")}</span></td><td class="num">${money(l.price,2)}</td><td class="num">${l.disc?l.disc+"%":"—"}</td><td class="num strong">${money(l.q*l.price*(1-(l.disc||0)/100),2)}</td></tr>`).join("")||`<tr><td colspan="6"><div class="empty">${tr("Sin líneas. Agregá productos para armar el documento.","No lines yet. Add products to build the document.")}</div></td></tr>`}
    </tbody><tfoot><tr><td colspan="4">${NV.t("subtotal")}</td><td class="num">${money(cc.ht,2)}</td>${editable?"<td></td>":""}</tr></tfoot></table>${editable?`<div style="padding:12px 14px"><button class="btn" data-addl>${icon("plus")}${NV.t("add_line")}</button></div>`:""}`;
    if(!editable)return;
    $$("[data-l]",lw).forEach(inp=>inp.onchange=()=>{const l=doc.lines[inp.dataset.l],f=inp.dataset.f;if(f==="p"){l.p=inp.value;const p=P(l.p);l.price=K.tp==="supplier"?p.cost:p.price}else l[f]=Number(inp.value)||0;save();drawLines();refreshTot()});
    $$("[data-rm]",lw).forEach(b=>b.onclick=()=>{doc.lines.splice(Number(b.dataset.rm),1);save();drawLines();refreshTot()});
    $("[data-addl]",lw).onclick=()=>{const p=saleable[0];doc.lines.push({p:p.id,q:1,price:K.tp==="supplier"?p.cost:p.price,disc:0});save();drawLines()};}
  function refreshTot(){NV.render()}
  drawLines();
  // payments + history
  const bottom=append(main,`<div class="g g2 mt"></div>`);
  if(doc.payments)bottom.appendChild(NV.el(`<div class="card"><div class="card-h"><h3>${icon("money")}${tr("Pagos","Payments")}</h3></div>${doc.payments.length?`<div class="tbl-w"><table class="t"><thead><tr><th>${NV.t("date")}</th><th>${tr("Medio","Method")}</th><th>${tr("Cuenta","Account")}</th><th class="r">${NV.t("amount")}</th></tr></thead><tbody>${doc.payments.map(p=>`<tr><td>${date(p.date)}</td><td>${esc(p.method)}</td><td>${esc(db().banks.find(b=>b.id===p.acc)?.short||"")}</td><td class="num strong">${money(p.amount,2)}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">${tr("Sin pagos registrados","No payments yet")}</div>`}</div>`));
  bottom.appendChild(NV.el(`<div class="card"><div class="card-h"><h3>${icon("clock")}${tr("Historial","History")}</h3></div><div class="card-b"><ul class="tl">${doc.hist.slice().reverse().map(h=>`<li><span class="tic">${icon("check")}</span><div><b>${esc(h.txt)}</b><p>${date(h.d)} · ${esc(NV.app.user.name)}</p></div></li>`).join("")}</ul></div></div>`));
  // actions
  const log=txt=>doc.hist.push({d:iso(TODAY),txt});
  $$("[data-act]",main).forEach(b=>b.onclick=()=>{const a=b.dataset.act;const need=()=>{if(!doc.lines.length){toast(tr("Agregá al menos una línea","Add at least one line"));return false}return true};
    const done=(msg)=>{save();toast(msg||NV.t("saved"));NV.render()};
    switch(a){
      case "validate":if(!need())return;doc.status=kind==="quote"?"open":kind==="order"?"validated":"unpaid";log(tr("Documento validado","Document validated"));if(kind==="invoice"){doc.date=iso(TODAY);doc.due=iso(addDays(TODAY,t.terms||30))}done();break;
      case "sign":doc.status="signed";log(tr("Presupuesto firmado por el cliente","Quote signed by customer"));done();break;
      case "nosign":doc.status="notsigned";log(tr("Presupuesto no aceptado","Quote not accepted"));done();break;
      case "toOrder":{if(t.kind==="prospect")t.kind="customer";const o=copyDoc(doc,"order","validated");log(tr("Pedido generado: ","Order created: ")+o.ref);save();toast(NV.t("created"));NV.go("#/commercial/order/"+o.id);break}
      case "toInvoice":{const i=copyDoc(doc,"invoice","draft");doc.status="billed";log(tr("Factura generada: ","Invoice created: ")+i.ref);save();toast(NV.t("created"));NV.go("#/billing/invoice/"+i.id);break}
      case "prep":doc.status="inprocess";log(tr("Preparación iniciada en expedición","Picking started"));done();break;
      case "ship":{const short=doc.lines.filter(l=>!l.p.startsWith("SV")&&P(l.p).stock.W3<l.q);if(short.length){modal({title:tr("Stock insuficiente en expedición","Not enough stock in shipping"),body:`<div class="note warn">${icon("alert")}<div>${short.map(l=>`<b>${l.p}</b> ${esc(pname(l.p))}: ${tr("necesitás","need")} ${l.q}, ${tr("hay","have")} ${P(l.p).stock.W3}`).join("<br>")}<br><br>${tr("Creá una orden de fabricación o transferí stock al almacén W3.","Create a manufacturing order or transfer stock to warehouse W3.")}</div></div>`});return}
        doc.lines.filter(l=>!l.p.startsWith("SV")).forEach(l=>addMove(l.p,"W3",-l.q,["Expedición a cliente","Customer shipment"],doc.ref));doc.status="shipped";log(tr("Mercadería despachada (remito R-","Goods shipped (delivery note R-")+String(Date.now()).slice(-6)+")");done(tr("Despacho registrado y stock descontado","Shipment recorded and stock updated"));break}
      case "toMO":{const lines=doc.lines.filter(l=>BOMS[l.p]);if(!lines.length){toast(tr("Ninguna línea tiene lista de materiales","No line has a bill of materials"));return}lines.forEach(l=>{const p=P(l.p);db().mos.push({id:NV.uid("M"),ref:nextRef("MO"),product:l.p,qty:l.q,produced:0,status:"validated",start:iso(TODAY),end:iso(addDays(TODAY,Math.ceil(l.q*BOMS[l.p][1]/16)+1)),line:p.line,origin:doc.ref,hist:[{d:iso(TODAY),txt:tr("Creada desde pedido ","Created from order ")+doc.ref}]})});log(tr(`${lines.length} orden(es) de fabricación creadas`,`${lines.length} manufacturing order(s) created`));done(NV.t("created"));break}
      case "pay":payModal(kind,doc);break;
      case "approve":if(!need())return;doc.status="approved";log(tr("Pedido aprobado","Order approved"));done();break;
      case "send":doc.status="ordered";log(tr("Pedido enviado al proveedor por email","Order emailed to supplier"));done();break;
      case "receive":doc.lines.forEach(l=>addMove(l.p,"W1",l.q,["Recepción de proveedor","Supplier receipt"],doc.ref));doc.status="received";log(tr("Mercadería recibida en Depósito Central","Goods received at main warehouse"));done(tr("Recepción registrada y stock actualizado","Receipt recorded and stock updated"));break;
      case "toSinvoice":{const i=copyDoc(doc,"sinvoice","unpaid");log(tr("Factura de proveedor registrada: ","Supplier invoice recorded: ")+i.ref);save();NV.go("#/purchases/invoice/"+i.id);break}
      case "print":docPrint(kind,doc);break;
      case "del":confirmBox(NV.t("confirm_del"),()=>{db()[K.coll]=db()[K.coll].filter(x=>x!==doc);save();toast(NV.t("deleted"));NV.go(K.list)},NV.t("del"));break;
    }});}

function pagePayments(main){H(main,{crumbs:[[tr("Facturación","Billing"),"#/billing"]],icon:"money",title:tr("Pagos recibidos","Payments received")});
  const rows=[];db().invoices.forEach(i=>i.payments.forEach(p=>rows.push({...p,inv:i})));
  table(main,{rows,name:"cobros",sort:"date",dir:-1,onRow:r=>NV.go("#/billing/invoice/"+r.inv.id),filters:[{k:"method",label:tr("Medio","Method"),options:[...new Set(rows.map(r=>r.method))]},{k:"acc",label:tr("Cuenta","Account"),options:db().banks.map(b=>[b.id,b.short])}],
    columns:[{k:"date",label:NV.t("date"),render:r=>date(r.date)},{k:"inv",label:tr("Factura","Invoice"),render:r=>`<span class="ref">${r.inv.ref}</span>`,text:r=>r.inv.ref,sv:r=>r.inv.ref},{k:"tp",label:NV.t("customer"),render:r=>esc(TP(r.inv.tp).name),text:r=>TP(r.inv.tp).name,sv:r=>TP(r.inv.tp).name},{k:"method",label:tr("Medio","Method")},{k:"acc",label:tr("Cuenta","Account"),render:r=>esc(db().banks.find(b=>b.id===r.acc)?.short||""),text:r=>db().banks.find(b=>b.id===r.acc)?.short||""},{k:"amount",label:NV.t("amount"),r:1,render:r=>`<b>${money(r.amount,2)}</b>`}],
    footer:a=>`<tr><td colspan="5">${NV.t("total")}</td><td class="num">${money(a.reduce((s,r)=>s+r.amount,0),2)}</td></tr>`});}
function pageAging(main){H(main,{crumbs:[[tr("Facturación","Billing"),"#/billing"]],icon:"chart",title:tr("Antigüedad de saldos","Aged receivables"),sub:tr("Saldos pendientes de clientes por días de vencidos.","Outstanding customer balances by days overdue.")});
  const B=[[tr("Por vencer","Not due"),-1e9,0],["1–30",1,30],["31–60",31,60],["61–90",61,90],["+90",91,1e9]];
  const rows={};db().invoices.filter(i=>calc(i).rest>.01&&i.status!=="draft").forEach(i=>{const od=daysBetween(i.due,iso(TODAY));const bi=B.findIndex(b=>od>=b[1]&&od<=b[2]);(rows[i.tp]=rows[i.tp]||{tp:i.tp,b:[0,0,0,0,0]}).b[bi]+=calc(i).rest});
  const list=Object.values(rows);const tots=B.map((_,i)=>list.reduce((s,r)=>s+r.b[i],0));
  const c=append(main,`<div class="card"><div class="card-b"><div class="chart sm"><canvas></canvas></div></div></div>`);
  chart($("canvas",c),{type:"bar",money:true,data:{labels:B.map(b=>b[0]),datasets:[{label:tr("Saldo","Balance"),data:tots,backgroundColor:[NV.css("--blue"),"#46A3FF","#D98200","#E0457B","#D93A3A"]}]}});
  append(main,`<div class="mt"></div>`);
  table(main,{rows:list,name:"antiguedad",sort:"t",dir:-1,onRow:r=>NV.go("#/tp/card/"+r.tp),columns:[{k:"tp",label:NV.t("customer"),render:r=>`<b>${esc(TP(r.tp).name)}</b>`,text:r=>TP(r.tp).name,sv:r=>TP(r.tp).name},...B.map((b,i)=>({k:"b"+i,label:b[0],r:1,sv:r=>r.b[i],text:r=>r.b[i].toFixed(2),render:r=>r.b[i]?`<span class="${i>=3?"down strong":""}">${money(r.b[i])}</span>`:"<span class='muted'>—</span>"})),{k:"t",label:NV.t("total"),r:1,sv:r=>r.b.reduce((a,b)=>a+b),text:r=>r.b.reduce((a,b)=>a+b).toFixed(2),render:r=>`<b>${money(r.b.reduce((a,b)=>a+b))}</b>`}],
    footer:()=>`<tr><td>${NV.t("total")}</td>${tots.map(x=>`<td class="num">${money(x)}</td>`).join("")}<td class="num">${money(tots.reduce((a,b)=>a+b))}</td></tr>`});}

