function pageBanks(main){H(main,{crumbs:[[tr("Bancos","Banks"),"#/bank"]],icon:"bank",title:tr("Bancos y caja","Banks & cash"),actions:`<button class="btn pri" data-a="newTx">${icon("plus")}${tr("Nuevo movimiento","New transaction")}</button>`});
  append(main,`<div class="g g3">${db().banks.map(b=>{const tx=db().btx.filter(x=>x.acc===b.id);const m=ym(iso(TODAY));const inn=tx.filter(x=>ym(x.date)===m&&x.amount>0).reduce((s,x)=>s+x.amount,0),out=tx.filter(x=>ym(x.date)===m&&x.amount<0).reduce((s,x)=>s+x.amount,0);return `<a class="card" href="#/bank/account/${b.id}" style="color:inherit;text-decoration:none"><div class="card-h"><h3>${icon("bank")}${esc(b.name)}</h3></div><div class="card-b"><div class="small muted">${tr("Saldo actual","Current balance")}</div><div style="font:800 26px var(--f-display);letter-spacing:-.02em">${money(bankBal(b.id),2)}</div><div class="small" style="display:flex;gap:14px;margin-top:8px"><span class="up">+${money(inn)}</span><span class="down">${money(out)}</span><span class="muted">${tr("este mes","this month")}</span></div><div class="small muted" style="margin-top:6px">${esc(b.number)} · ${tx.length} ${tr("movimientos","transactions")}</div></div></a>`}).join("")}</div>`);
  const c=append(main,`<div class="card mt"><div class="card-h"><h3>${icon("chart")}${tr("Flujo de caja mensual","Monthly cash flow")}</h3></div><div class="card-b"><div class="chart"><canvas></canvas></div></div></div>`);
  const ms=monthsBack(12);const tx=db().btx;
  chart($("canvas",c),{type:"bar",money:true,data:{labels:ms.map(m=>m.label),datasets:[{label:tr("Ingresos","Inflows"),data:ms.map(m=>tx.filter(x=>ym(x.date)===m.key&&x.amount>0&&x.cat!=="transfer").reduce((s,x)=>s+x.amount,0)),color:"#12A06A"},{label:tr("Egresos","Outflows"),data:ms.map(m=>-tx.filter(x=>ym(x.date)===m.key&&x.amount<0).reduce((s,x)=>s+x.amount,0)),color:"#E0457B"}]}});bindActs(main)}
function pageBank(main,{id}){const b=db().banks.find(x=>x.id===id);if(!b)return notFound(main);
  H(main,{crumbs:[[tr("Bancos","Banks"),"#/bank"],b.short],icon:"bank",title:b.name,sub:`${esc(b.number)} · ${tr("Saldo","Balance")}: <b>${money(bankBal(id),2)}</b>`,actions:`<button class="btn pri" data-a="newTx" data-acc="${id}">${icon("plus")}${tr("Nuevo movimiento","New transaction")}</button>`});
  let run=b.opening;const rows=db().btx.filter(x=>x.acc===id).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>{run+=x.amount;return {...x,bal:run}});
  const c=append(main,`<div class="card"><div class="card-b"><div class="chart sm"><canvas></canvas></div></div></div><div class="mt"></div>`);
  chart($("canvas",c),{type:"line",money:true,data:{labels:rows.map(r=>date(r.date)),datasets:[{label:tr("Saldo","Balance"),data:rows.map(r=>r.bal),fill:true}]},options:{scales:{x:{display:false},y:{beginAtZero:false,grid:{color:NV.css("--line-2")},ticks:{callback:v=>"$"+NV.kfmt(v)}}}}});
  const CAT={in:["Cobranza","Collection"],supplier:["Proveedores","Suppliers"],salary:["Sueldos","Payroll"],tax:["Impuestos","Taxes"],utility:["Servicios","Utilities"],misc:["Varios","Misc."],transfer:["Transferencia","Transfer"],other:["Otros","Other"]};
  table(main,{rows:rows.slice().reverse(),name:"movimientos_banco",pageSize:15,filters:[{k:"cat",label:tr("Categoría","Category"),options:Object.entries(CAT)}],columns:[{k:"date",label:NV.t("date"),render:x=>date(x.date)},{k:"label",label:tr("Concepto","Description"),render:x=>`<b>${esc(x.label)}</b>`},{k:"cat",label:tr("Categoría","Category"),render:x=>`<span class="tag">${esc(NV.L(CAT[x.cat]||CAT.other))}</span>`,text:x=>NV.L(CAT[x.cat]||CAT.other)},{k:"in",label:tr("Crédito","Credit"),r:1,sv:x=>x.amount,text:x=>x.amount>0?x.amount:"",render:x=>x.amount>0?`<span class="up">${money(x.amount,2)}</span>`:""},{k:"out",label:tr("Débito","Debit"),r:1,sv:x=>-x.amount,text:x=>x.amount<0?-x.amount:"",render:x=>x.amount<0?`<span class="down">${money(-x.amount,2)}</span>`:""},{k:"bal",label:tr("Saldo","Balance"),r:1,render:x=>`<b>${money(x.bal,2)}</b>`}]});bindActs(main)}
function newTx(acc){formModal({title:tr("Nuevo movimiento bancario","New bank transaction"),fields:[{k:"acc",label:tr("Cuenta","Account"),type:"select",options:db().banks.map(b=>[b.id,b.name]),def:acc||"B1",full:1},{k:"dir",label:tr("Tipo","Type"),type:"select",options:[["in",["Ingreso","Inflow"]],["out",["Egreso","Outflow"]]]},{k:"amount",label:tr("Importe (US$)","Amount (US$)"),type:"number",step:"0.01",req:1},{k:"label",label:tr("Concepto","Description"),req:1,full:1},{k:"cat",label:tr("Categoría","Category"),type:"select",options:[["other",["Otros","Other"]],["tax",["Impuestos","Taxes"]],["utility",["Servicios","Utilities"]],["salary",["Sueldos","Payroll"]],["misc",["Varios","Misc."]]]}],onSave:v=>{if(!(v.amount>0))return false;addTx(v.acc,v.dir==="out"?-v.amount:v.amount,v.label,"",v.cat);save();toast(NV.t("created"));NV.go("#/bank/account/"+v.acc)}})}

